import java.io.IOException;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author out_of_the_box
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        DNekoAndAkisPrank solver = new DNekoAndAkisPrank();
        solver.solve(1, in, out);
        out.close();
    }

    static class DNekoAndAkisPrank {
        private static final int MOD = 1000000007;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();
            out.print(solve(n));
        }

        private int solve(int n) {
            int N = 2 * n;
            int[][][] dp = new int[N + 1][N + 1][2];
            dp[0][0][0] = 0;
            dp[0][0][1] = 0;
            for (int i = 1; i <= N; i++) {
                for (int j = 0; j <= i; j++) {
                    for (int k = 0; k <= 1; k++) {
                        dp[i][j][k] = 0;
                        if (k == 1) {
                            if (i - j >= 2) {
                                dp[i][j][k] = MathUtility.add(dp[i][j][k], dp[i - 1][j + 1][0], MOD);
                            }
                            if (j > 0) {
                                dp[i][j][k] = MathUtility.add(dp[i][j][k], dp[i - 1][j - 1][0], MOD);
                            }
                        } else {
                            dp[i][j][k] = Math.max(getVal(dp, i, j, false, false),
                                    Math.max(getVal(dp, i, j, false, true),
                                            getVal(dp, i, j, true, false)));
                        }
                    }
                }
            }
//        for (int i = 0; i<=N; i++) {
//            for (int j = 0; j<= N; j++) {
//                System.out.print("(");
//                System.out.print(dp[i][j][0]);
//                System.out.print(",");
//                System.out.print(dp[i][j][1]);
//                System.out.print(") ");
//            }
//            System.out.println();
//        }
//        System.out.println();
            return dp[N][0][0];
        }

        private int getVal(int[][][] dp, int i, int j, boolean selectStart, boolean selectEnd) {
            int ret = 0;
            if (i - j >= 2) {
                if (selectStart) {
                    ret = MathUtility.add(ret, dp[i - 1][j + 1][1], MOD);
                    ret = MathUtility.add(ret, 1, MOD);
                } else {
                    ret = MathUtility.add(ret, dp[i - 1][j + 1][0], MOD);
                }
            }
            if (j > 0) {
                if (selectEnd) {
                    ret = MathUtility.add(ret, dp[i - 1][j - 1][1], MOD);
                    ret = MathUtility.add(ret, 1, MOD);
                } else {
                    ret = MathUtility.add(ret, dp[i - 1][j - 1][0], MOD);
                }
            }
            return ret;
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void print(int i) {
            writer.print(i);
        }

    }

    static class MathUtility {
        public static int add(int a, int b, int MOD) {
            int res = a + b;
            if (res >= MOD) {
                res -= MOD;
            }
            return res;
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}


